replacement="if (index.schemaVersion !== 2 || !Array.isArray(index.works) || !version) throw new Error('新資料格式無效。'); let shipping: ShippingRecord[] = []; try { const parsed = JSON.parse(await readJson(env, 'public/data/shipping.json', files, paths)) as ShippingData; if (parsed.schemaVersion === 1 && Array.isArray(parsed.records)) shipping = parsed.records; } catch {} return { index, version, shipping, headSha, baseTreeSha: head.tree.sha, files, blobs, paths };"
