    new=old+"\nfunction validateShipping(value: unknown, remote: RemoteState): ShippingRecord { if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('運費紀錄格式無效。'); const v=value as Record<string,unknown>; if(typeof v.id!=='string'||!/^[A-Za-z0-9_-]+$/.test(v.id)) throw new Error('運費 ID 格式無效。'); if(typeof v.amount!=='number'||!Number.isFinite(v.amount)||v.amount<0) throw new Error('運費金額無效。'); if(typeof v.currency!=='string'||!v.currency.trim()) throw new Error('運費幣別為必填。'); if(v.date!==undefined&&typeof v.date!=='string') throw new Error('運費日期無效。'); if(v.carrier!==undefined&&typeof v.carrier!=='string') throw new Error('物流欄位無效。'); if(v.note!==undefined&&typeof v.note!=='string') throw new Error('備註欄位無效。'); if(!Array.isArray(v.itemIds)||v.itemIds.length===0||v.itemIds.some(x=>typeof x!=='string')) throw new Error('至少需要一個關聯周邊。'); const ids=[...new Set(v.itemIds as string[])]; for(const id of ids) if(!remote.items.has(id)) throw new Error(`找不到關聯周邊：${id}`); return { id:v.id as string, amount:v.amount as number, currency:(v.currency as string).trim(), ...(typeof v.date==='string'&&v.date?{date:v.date}:{}), ...(typeof v.carrier==='string'&&v.carrier.trim()?{carrier:v.carrier.trim()}:{}), ...(typeof v.note==='string'&&v.note.trim()?{note:v.note.trim()}:{}), itemIds:ids }; }\nasync function shippingResponse(env: Env, origin: string): Promise<Response> { const remote=await baseRemote(env); return ok(remote.shipping,origin); }\nasync function upsertShipping(env: Env, input: unknown, origin: string): Promise<Response> { const remote=await loadRemote(env); const record=validateShipping((input as {shipping?:unknown}|null)?.shipping,remote); const exists=remote.shipping.some(x=>x.id===record.id); const records=[...remote.shipping.filter(x=>x.id!==record.id),record]; const version=bumpPatch(remote.version); await createAtomicCommit(env,remote,[{path:'public/data/shipping.json',content:jsonFile({schemaVersion:1,records})},{path:'public/data/version.json',content:jsonFile({version})}],`${exists?'fix':'feat'}: ${exists?'update':'add'} shipping ${record.id}`); return dataResponse(env,origin); }\nasync function removeShipping(env: Env, id: string, origin: string): Promise<Response> { const remote=await loadRemote(env); if(!remote.shipping.some(x=>x.id===id)) return fail('SHIPPING_NOT_FOUND','找不到運費紀錄。',404,origin); const records=remote.shipping.filter(x=>x.id!==id); const version=bumpPatch(remote.version); await createAtomicCommit(env,remote,[{path:'public/data/shipping.json',content:jsonFile({schemaVersion:1,records})},{path:'public/data/version.json',content:jsonFile({version})}],`fix: delete shipping ${id}`); return dataResponse(env,origin); }"
